const item = $input.item;
const j = item.json || {};
const jobId = j.jobId || null;
const assetKey = j.assetKey || "featured-main";
const binaryObj = item.binary && item.binary.data ? item.binary.data : null;

if (!binaryObj || !binaryObj.data) {
  return {
    json: {
      ok: false,
      jobId,
      errorCode: "MISSING_BINARY_IMAGE",
      errorMessage: "No binary image data supplied for image optimization."
    }
  };
}

let sharp = null;
try {
  sharp = require("sharp");
} catch (e) {
  sharp = null;
}

if (!sharp) {
  return {
    json: {
      ok: false,
      jobId,
      errorCode: "IMAGE_CONVERTER_NOT_CONFIGURED",
      errorMessage: "Image converter (Sharp module) is not configured in this n8n instance. Cannot perform WebP conversion."
    }
  };
}

const crypto = require("crypto");
const inputBuffer = Buffer.from(binaryObj.data, "base64");

return sharp(inputBuffer)
  .webp({ quality: 82 })
  .toBuffer()
  .then(webpBuffer => {
    const fileSizeBytes = webpBuffer.length;
    const checksum = crypto.createHash("sha256").update(webpBuffer).digest("hex");
    const base64WebP = webpBuffer.toString("base64");
    return {
      json: {
        ok: true,
        jobId,
        assetKey,
        fileSizeBytes,
        checksum,
        mimeType: "image/webp"
      },
      binary: {
        data: {
          data: base64WebP,
          mimeType: "image/webp",
          fileName: `${assetKey}.webp`,
          fileExtension: "webp",
          fileSize: `${fileSizeBytes} B`
        }
      }
    };
  })
  .catch(err => {
    return {
      json: {
        ok: false,
        jobId,
        errorCode: "WEBP_CONVERSION_FAILED",
        errorMessage: "Sharp WebP conversion failed: " + err.message
      }
    };
  });

const item = $input.item;
const opt = item.json || {};
const norm = {
  success: true,
  jobId: opt.jobId,
  status: "ASSET_OPTIMIZED",
  message: "Image converted to WebP and optimized successfully.",
  data: {
    assetKey: opt.assetKey,
    fileSizeBytes: opt.fileSizeBytes,
    checksum: opt.checksum,
    mimeType: opt.mimeType
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["upload_media"]
};
return {
  json: norm,
  binary: item.binary
};

const j = $json || {};
const code = j.errorCode || "IMAGE_CONVERTER_NOT_CONFIGURED";
const message = j.errorMessage || "Image converter is not configured in this n8n instance.";
const status = code === "IMAGE_CONVERTER_NOT_CONFIGURED" ? "NOT_CONFIGURED" : "FAILED";
return {
  json: {
    success: false,
    jobId: j.jobId || null,
    status,
    message,
    data: null,
    warnings: [],
    errors: [{ code, language: null, path: null, message }],
    nextAllowedActions: ["retry", "cancel"]
  },
  binary: $input.item ? $input.item.binary : undefined
};
